(function () {
  var W = 900, H = 430;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

  // ---- geometry ----
  var L = { x: 240, y: 205 }, R = { x: 660, y: 205 }, RAD = 118;
  var NECK_Y = 205, NECK_H = 52;

  // seeded rng
  function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
  var rnd = mulberry32(20240607);
  function inCircle(c, r) {
    while (true) {
      var x = c.x + (rnd() * 2 - 1) * r, y = c.y + (rnd() * 2 - 1) * r;
      var dx = x - c.x, dy = y - c.y;
      if (dx * dx + dy * dy <= r * r) return { x: x, y: y };
    }
  }

  // ---- static apparatus ----
  var bulbFill = '#cfe2e2', bulbStroke = '#9cc0c0';
  // neck
  draw.rect(R.x - L.x, NECK_H).move(L.x, NECK_Y - NECK_H / 2).fill(bulbFill).stroke({ color: bulbStroke, width: 2 });
  // bulbs
  var leftBulb = draw.circle(RAD * 2).center(L.x, L.y).fill(bulbFill).stroke({ color: bulbStroke, width: 2.5 });
  var rightBulb = draw.circle(RAD * 2).center(R.x, R.y).fill(bulbFill).stroke({ color: bulbStroke, width: 2.5 });

  // stopcock (stem + rotating handle)
  var valveX = (L.x + R.x) / 2;
  draw.rect(14, 46).center(valveX, NECK_Y).fill('#b9d2d2').stroke({ color: '#7fa3a3', width: 1.5 });
  draw.line(valveX, NECK_Y - 22, valveX, NECK_Y - 40).stroke({ color: '#7fa3a3', width: 4, linecap: 'round' });
  var handle = draw.rect(40, 9).rx(4).center(valveX, NECK_Y - 42).fill('#8fb6b6').stroke({ color: '#6f9393', width: 1.5 });
  var stopcockGroup = draw.group();
  // re-parent handle visuals into a group we rotate about the knob
  var knob = draw.circle(12).center(valveX, NECK_Y - 42).fill('#a9c9c9').stroke({ color: '#6f9393', width: 1.5 });

  // species labels
  function haloText(x, y, str, size, anchor) {
    return draw.text(str).move(x, y).font({ size: size, family: 'sans-serif', anchor: anchor || 'middle', weight: 600 })
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round', fill: '#222' });
  }
  haloText(L.x, L.y - RAD - 26, 'H₂', 22);
  haloText(R.x, R.y - RAD - 26, 'O₂', 22);

  // dynamic caption
  var caption = draw.text('').move(W / 2, H - 34).font({ size: 17, family: 'sans-serif', anchor: 'middle', fill: '#222' });

  // ---- legend (top-right) ----
  var legX = W - 178, legY = 14;
  draw.rect(170, 56).move(legX - 8, legY - 6).fill('#ffffff').opacity(0.85).stroke({ color: '#ccc', width: 1 }).rx(5);
  var legDot1 = draw.circle(13).center(legX + 4, legY + 12);
  var legTxt1 = draw.text('').move(legX + 16, legY + 5).font({ size: 12, family: 'sans-serif', fill: '#222' });
  var legDot2 = draw.circle(13).center(legX + 4, legY + 36);
  var legTxt2 = draw.text('').move(legX + 16, legY + 29).font({ size: 12, family: 'sans-serif', fill: '#222' });

  // ---- particles ----
  var N = 30;
  var particles = [];
  function makeParticles(homeBulb, species) {
    for (var i = 0; i < N; i++) {
      var home = inCircle(homeBulb, RAD * 0.82);
      var target = inCircle(rnd() < 0.5 ? L : R, RAD * 0.82);
      var start, dur;
      if (species === 'H2') { start = rnd() * 0.25; dur = 0.35 + rnd() * 0.18; }
      else { start = 0.10 + rnd() * 0.35; dur = 0.45 + rnd() * 0.20; }
      var el = draw.circle(13).center(home.x, home.y).stroke({ width: 1 });
      particles.push({
        el: el, hx: home.x, hy: home.y, tx: target.x, ty: target.y,
        start: start, dur: dur, species: species,
        ph: rnd() * Math.PI * 2, ph2: rnd() * Math.PI * 2, f1: 1 + rnd() * 2, f2: 1 + rnd() * 2
      });
    }
  }
  makeParticles(L, 'H2');
  makeParticles(R, 'O2');

  // ---- state ----
  var currentT = 0, massMode = false, playing = false, jitterAmp = 0, rafId = 0, lastTs = 0;

  var COLORS = {
    species: { H2: '#ffffff', H2s: '#b9b9b9', O2: '#d62728', O2s: '#a01818' },
    mass:    { H2: '#17becf', H2s: '#0e8a96', O2: '#e6550d', O2s: '#a83c06' }
  };

  function smooth(p) { p = Math.max(0, Math.min(1, p)); return p * p * (3 - 2 * p); }

  function progressFor(p, t) {
    var bias = 1;
    if (massMode) bias = (p.species === 'H2') ? 1.18 : 0.88;
    return smooth(((t - p.start) / p.dur) * bias);
  }

  function recolor() {
    var c = massMode ? COLORS.mass : COLORS.species;
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      if (p.species === 'H2') p.el.fill(c.H2).stroke({ color: c.H2s, width: 1 });
      else p.el.fill(c.O2).stroke({ color: c.O2s, width: 1 });
    }
  }

  function updateLegend() {
    var c = massMode ? COLORS.mass : COLORS.species;
