      legDot2.fill(c.O2).stroke({ color: c.O2s, width: 1 }); legTxt2.text('slow — heavy (O₂)');
    } else {
      legDot1.fill(c.H2).stroke({ color: c.H2s, width: 1 }); legTxt1.text('H₂ molecules');
      legDot2.fill(c.O2).stroke({ color: c.O2s, width: 1 }); legTxt2.text('O₂ molecules');
    }
  }

  function captionFor(t) {
    if (t < 0.05) return 'Stopcock closed   (a)';
    if (t < 0.6) return 'Stopcock open   (b)';
    return 'Some time after stopcock open   (c)';
  }

  function redraw() {
    var t = currentT;
    // stopcock handle: vertical (closed) -> horizontal (open)
    var open = Math.max(0, Math.min(1, t / 0.15));
    handle.transform({ rotate: 90 * open, cx: valveX, cy: NECK_Y - 42 });
    caption.text(captionFor(t));
    var amp = jitterAmp;
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i], pr = progressFor(p, t);
      var x = p.hx + (p.tx - p.hx) * pr;
      var y = p.hy + (p.ty - p.hy) * pr;
      if (amp > 0) {
        x += Math.sin(performance.now() * 0.004 * p.f1 + p.ph) * amp;
        y += Math.cos(performance.now() * 0.004 * p.f2 + p.ph2) * amp;
      }
      p.el.center(x, y);
    }
  }

  // ---- controls ----
  window.update_elapsedTime = function (v) {
    currentT = v;
    if (!playing) redraw();
  };

  window.setMassMode = function (on) {
    massMode = !!on;
    recolor(); updateLegend(); redraw();
  };

  window.trigger_playDiffusion = function () {
    playing = !playing;
    var btn = document.getElementById('playDiffusionBtn');
    if (playing) {
      btn.textContent = '⏸ Pause'; btn.classList.add('active');
      jitterAmp = 2.6; lastTs = performance.now();
      rafId = requestAnimationFrame(loop);
    } else {
      btn.textContent = '▶ Play diffusion'; btn.classList.remove('active');
      jitterAmp = 0; cancelAnimationFrame(rafId); redraw();
    }
  };

  function loop(ts) {
    if (!playing) return;
    var dt = (ts - lastTs) / 1000; lastTs = ts;
    currentT += dt * 0.22;            // ~4.5 s per full cycle
    if (currentT > 1) currentT = 0;   // loop
    var sl = document.getElementById('elapsedTimeInput');
    sl.value = currentT.toFixed(2);
    document.getElementById('elapsedTimeVal').value = currentT.toFixed(2);
    redraw();
    rafId = requestAnimationFrame(loop);
  }

  // ---- tooltips / popups ----
