// @FIGURE_CODE_BEGIN
(function () {
  var W = 900, H = 545;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

  // ---- palette ----
  var bulbFill = '#cfe2e2', bulbStroke = '#9cc0c0';
  var valveFill = '#b9d2d2', valveStroke = '#7fa3a3';
  var handleFill = '#8fb6b6', handleStroke = '#6f9393';
  var COLORS = {
    species: { H2: '#ffffff', H2s: '#b9b9b9', O2: '#d62728', O2s: '#a01818' },
    mass:    { H2: '#17becf', H2s: '#0e8a96', O2: '#e6550d', O2s: '#a83c06' }
  };

  // ---- seeded rng ----
  function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
  function inCircle(rnd,c,r){for(;;){var x=c.x+(rnd()*2-1)*r,y=c.y+(rnd()*2-1)*r,dx=x-c.x,dy=y-c.y;if(dx*dx+dy*dy<=r*r)return{x:x,y:y};}}
  function smooth(p){p=Math.max(0,Math.min(1,p));return p*p*(3-2*p);}

  // ---- valve drawing (vertical handle = closed, horizontal = open) ----
  function drawValve(g, vx, vy, openFrac, s) {
    s = s || 1;
    var bodyW = 16*s, bodyH = 40*s;
    g.rect(bodyW, bodyH).center(vx, vy).fill(valveFill).stroke({color:valveStroke,width:1.5});
    // bore indicator: vertical slot when closed, horizontal opening when open
    g.line(vx, vy-12*s, vx, vy+12*s).stroke({color:'#5f8383',width:2.5*s,opacity:1-openFrac,linecap:'round'});
    g.line(vx-7*s, vy, vx+7*s, vy).stroke({color:'#eef6f6',width:3*s,opacity:openFrac,linecap:'round'});
    // stem
    var pivotY = vy - bodyH/2 - 12*s;
    g.line(vx, vy-bodyH/2, vx, pivotY).stroke({color:valveStroke,width:3.5*s,linecap:'round'});
    // handle: vertical (closed) -> rotates to horizontal (open)
    var h = g.rect(8*s, 30*s).rx(3*s).center(vx, pivotY).fill(handleFill).stroke({color:handleStroke,width:1.5});
    h.transform({rotate:90*openFrac, cx:vx, cy:pivotY});
    var knob = g.circle(11*s).center(vx, pivotY).fill('#a9c9c9').stroke({color:handleStroke,width:1.5});
    return knob;
  }

  // ---- static apparatus (bulbs + neck + valve + dots) ----
  function drawApparatus(g, cxL, cy, cxR, rad, t, openFrac, seed) {
    var neckHalf = 22 * (rad/105);
    g.rect(cxR-cxL, neckHalf*2).move(cxL, cy-neckHalf).fill(bulbFill).stroke({color:bulbStroke,width:2});
    g.circle(rad*2).center(cxL, cy).fill(bulbFill).stroke({color:bulbStroke,width:2.5});
    g.circle(rad*2).center(cxR, cy).fill(bulbFill).stroke({color:bulbStroke,width:2.5});
    drawValve(g, (cxL+cxR)/2, cy, openFrac, rad/105);
    // dots
    var rnd = mulberry32(seed), N = 30, dotR = Math.max(3, rad*0.062);
    var L={x:cxL,y:cy}, R={x:cxR,y:cy};
    function place(species){
      for(var i=0;i<N;i++){
        var home = inCircle(rnd, species==='H2'?L:R, rad*0.82);
        var target = inCircle(rnd, rnd()<0.5?L:R, rad*0.82);
        var start = species==='H2' ? rnd()*0.25 : 0.10+rnd()*0.35;
        var dur = species==='H2' ? 0.35+rnd()*0.18 : 0.45+rnd()*0.20;
        var bias = species==='H2' ? 1.18 : 0.88;
        var pr = smooth(((t-start)/dur)*bias);
        var x = home.x+(target.x-home.x)*pr, y = home.y+(target.y-home.y)*pr;
        var c = COLORS.species;
        g.circle(dotR*2).center(x,y)
          .fill(species==='H2'?c.H2:c.O2).stroke({color:species==='H2'?c.H2s:c.O2s,width:1});
      }
    }
    place('H2'); place('O2');
  }

  function haloText(x,y,str,size,anchor){
    return draw.text(str).move(x,y).font({size:size,family:'sans-serif',anchor:anchor||'middle',weight:600})
      .attr({'paint-order':'stroke',stroke:'#fff','stroke-width':4,'stroke-linejoin':'round',fill:'#222'});
  }

  // ================= MAIN interactive apparatus =================
  var L={x:270,y:175}, R={x:630,y:175}, RAD=105, NECK_Y=175, NECK_HALF=22;
  var mainG = draw.group();
  mainG.rect(R.x-L.x, NECK_HALF*2).move(L.x, NECK_Y-NECK_HALF).fill(bulbFill).stroke({color:bulbStroke,width:2});
  var leftBulb = mainG.circle(RAD*2).center(L.x,L.y).fill(bulbFill).stroke({color:bulbStroke,width:2.5});
  var rightBulb = mainG.circle(RAD*2).center(R.x,R.y).fill(bulbFill).stroke({color:bulbStroke,width:2.5});
  var valveX=(L.x+R.x)/2;
  // valve body + bore (animated separately)
  mainG.rect(16,40).center(valveX,NECK_Y).fill(valveFill).stroke({color:valveStroke,width:1.5});
  var closedSlot = mainG.line(valveX,NECK_Y-12,valveX,NECK_Y+12).stroke({color:'#5f8383',width:2.5,linecap:'round'});
  var openBore = mainG.line(valveX-7,NECK_Y,valveX+7,NECK_Y).stroke({color:'#eef6f6',width:3,linecap:'round',opacity:0});
  var pivotY = NECK_Y-20-12;
  mainG.line(valveX,NECK_Y-20,valveX,pivotY).stroke({color:valveStroke,width:3.5,linecap:'round'});
  var handle = mainG.rect(8,30).rx(3).center(valveX,pivotY).fill(handleFill).stroke({color:handleStroke,width:1.5});
  var knob = mainG.circle(11).center(valveX,pivotY).fill('#a9c9c9').stroke({color:handleStroke,width:1.5});

  haloText(L.x, L.y-RAD-26, 'H₂', 22);
  haloText(R.x, R.y-RAD-26, 'O₂', 22);
  var caption = draw.text('').move(W/2, 300).font({size:17,family:'sans-serif',anchor:'middle',fill:'#222'});

  // legend
  var legX=770, legY=14;
  draw.rect(120,52).move(legX-8,legY-6).fill('#fff').opacity(0.88).stroke({color:'#ccc',width:1}).rx(5);
  var legDot1=draw.circle(12).center(legX+4,legY+11);
  var legTxt1=draw.text('').move(legX+15,legY+4).font({size:11,family:'sans-serif',fill:'#222'});
  var legDot2=draw.circle(12).center(legX+4,legY+34);
  var legTxt2=draw.text('').move(legX+15,legY+27).font({size:11,family:'sans-serif',fill:'#222'});

  // ---- animated particles ----
  var N=30, particles=[];
  (function(){
    var rnd=mulberry32(20240607);
    function mk(home,species){
      for(var i=0;i<N;i++){
        var h=inCircle(rnd,home,RAD*0.82);
        var tg=inCircle(rnd, rnd()<0.5?L:R, RAD*0.82);
        var start=species==='H2'?rnd()*0.25:0.10+rnd()*0.35;
        var dur=species==='H2'?0.35+rnd()*0.18:0.45+rnd()*0.20;
        var el=draw.circle(13).center(h.x,h.y).stroke({width:1});
        particles.push({el:el,hx:h.x,hy:h.y,tx:tg.x,ty:tg.y,start:start,dur:dur,species:species,
          ph:rnd()*6.283,ph2:rnd()*6.283,f1:1+rnd()*2,f2:1+rnd()*2});
      }
    }
    mk(L,'H2'); mk(R,'O2');
  })();

  var currentT=0, massMode=false, playing=false, jitterAmp=0, rafId=0, lastTs=0;

  function progressFor(p,t){var bias=massMode?((p.species==='H2')?1.18:0.88):((p.species==='H2')?1.18:0.88);return smooth(((t-p.start)/p.dur)*bias);}
  function recolor(){var c=massMode?COLORS.mass:COLORS.species;for(var i=0;i<particles.length;i++){var p=particles[i];if(p.species==='H2')p.el.fill(c.H2).stroke({color:c.H2s,width:1});else p.el.fill(c.O2).stroke({color:c.O2s,width:1});}}
  function updateLegend(){var c=massMode?COLORS.mass:COLORS.species;
    legDot1.fill(c.H2).stroke({color:c.H2s,width:1}); legDot2.fill(c.O2).stroke({color:c.O2s,width:1});
    if(massMode){legTxt1.text('fast — light (H₂)');legTxt2.text('slow — heavy (O₂)');}
    else{legTxt1.text('H₂ molecules');legTxt2.text('O₂ molecules');}}
  function captionFor(t){if(t<0.05)return 'Stopcock closed   (a)';if(t<0.6)return 'Stopcock open   (b)';return 'Some time after Stopcock open   (c)';}

  function redraw(){
    var t=currentT, open=Math.max(0,Math.min(1,t/0.15));
    handle.transform({rotate:90*open,cx:valveX,cy:pivotY});
    closedSlot.attr({opacity:1-open}); openBore.attr({opacity:open});
    caption.text(captionFor(t));
    var amp=jitterAmp, now=performance.now();
    for(var i=0;i<particles.length;i++){var p=particles[i],pr=progressFor(p,t);
      var x=p.hx+(p.tx-p.hx)*pr, y=p.hy+(p.ty-p.hy)*pr;
      if(amp>0){x+=Math.sin(now*0.004*p.f1+p.ph)*amp;y+=Math.cos(now*0.004*p.f2+p.ph2)*amp;}
      p.el.center(x,y);}
  }

  // ================= THREE static thumbnails (a)(b)(c) =================
  var thumbs=[
    {cx:150,t:0,open:0,lines:['Stopcock closed','(a)'],seed:11},
    {cx:450,t:0.3,open:1,lines:['Stopcock open','(b)'],seed:22},
    {cx:750,t:1,open:1,lines:['Some time after','Stopcock open  (c)'],seed:33}
  ];
  var tRad=52, tCy=432;
  thumbs.forEach(function(th){
    var g=draw.group();
    drawApparatus(g, th.cx-78, tCy, th.cx+78, tRad, th.t, th.open, th.seed);
    var c1=draw.text(th.lines[0]).move(th.cx,500).font({size:13,family:'sans-serif',anchor:'middle',fill:'#222'});
    var c2=draw.text(th.lines[1]).move(th.cx,516).font({size:13,family:'sans-serif',anchor:'middle',fill:'#222'});
    g.css('cursor','pointer')
      .on('mousemove',function(e){showTooltip('Click to jump the live demo to state '+th.lines[th.lines.length-1]+'.',e);})
      .on('mouseleave',hideTooltip)
      .on('click',function(){jumpTo(th.t);});
    c1.css('cursor','pointer').on('click',function(){jumpTo(th.t);});
    c2.css('cursor','pointer').on('click',function(){jumpTo(th.t);});
  });

  function jumpTo(t){
    if(playing) trigger_playDiffusion();
    currentT=t;
    var sl=document.getElementById('elapsedTimeInput'); sl.value=t.toFixed(2);
    document.getElementById('elapsedTimeVal').value=t.toFixed(2);
    redraw();
  }

  // ---- controls ----
  window.update_elapsedTime=function(v){currentT=v;if(!playing)redraw();};
  window.setMassMode=function(on){massMode=!!on;recolor();updateLegend();redraw();};
  window.trigger_playDiffusion=function(){
    playing=!playing;var btn=document.getElementById('playDiffusionBtn');
    if(playing){btn.textContent='⏸ Pause';btn.classList.add('active');jitterAmp=2.6;lastTs=performance.now();rafId=requestAnimationFrame(loop);}
    else{btn.textContent='▶ Play diffusion';btn.classList.remove('active');jitterAmp=0;cancelAnimationFrame(rafId);redraw();}
  };
  function loop(ts){if(!playing)return;var dt=(ts-lastTs)/1000;lastTs=ts;currentT+=dt*0.22;if(currentT>1)currentT=0;
    var sl=document.getElementById('elapsedTimeInput');sl.value=currentT.toFixed(2);document.getElementById('elapsedTimeVal').value=currentT.toFixed(2);
    redraw();rafId=requestAnimationFrame(loop);}

  // ---- tooltips / popups ----
  leftBulb.css('cursor','pointer')
    .on('mousemove',function(e){showTooltip('Left bulb: initially holds the lighter gas H₂ (white dots).',e);})
    .on('mouseleave',hideTooltip)
    .on('click',function(){showPopup('Hydrogen side','H₂ has a molar mass of 2 g/mol. Being light, its molecules move faster on average, so they cross the neck and spread down their concentration gradient more quickly than O₂.');});
  rightBulb.css('cursor','pointer')
    .on('mousemove',function(e){showTooltip('Right bulb: initially holds the heavier gas O₂ (red dots).',e);})
    .on('mouseleave',hideTooltip)
    .on('click',function(){showPopup('Oxygen side','O₂ has a molar mass of 32 g/mol. Heavier molecules diffuse more slowly, so the red dots lag behind the white ones at intermediate times — the qualitative basis of Graham’s law.');});
  knob.css('cursor','pointer')
    .on('mousemove',function(e){showTooltip('Stopcock: vertical = closed, horizontal = open.',e);})
    .on('mouseleave',hideTooltip)
    .on('click',function(){showPopup('Stopcock','Opening the stopcock connects the two bulbs, allowing each gas to diffuse down its own concentration gradient until the mixture is uniform.');});

  // ---- demo steps ----
  var steps=[
    {title:'Stopcock closed',narration:'With the valve shut, all white H₂ dots stay in the left bulb and all red O₂ dots in the right bulb — two sharp concentration gradients with no mixing.',t:0,mass:false},
    {title:'Just opened',narration:'Moments after opening, more white H₂ dots have already crossed into the right bulb than red O₂ dots have crossed left, because the lighter gas moves faster down its gradient.',t:0.25,mass:false},
    {title:'See the mass effect',narration:'Switch to color-by-mass at this same early time: the “fast” light-gas tint has spread much further than the “slow” heavy-gas tint, isolating the rate difference that species-coloring hides.',t:0.25,mass:true},
    {title:'Equilibrium',narration:'At full elapsed time both colors are spread roughly uniformly across both bulbs — the concentration gradients have equalized and net diffusion has stopped.',t:1,mass:false}
  ];
  var stepIdx=0;
  function applyStep(i){
    stepIdx=Math.max(0,Math.min(steps.length-1,i));var s=steps[stepIdx];
    var sl=document.getElementById('elapsedTimeInput');sl.value=s.t;document.getElementById('elapsedTimeVal').value=s.t.toFixed(2);
    update_elapsedTime(s.t);
    var cb=document.getElementById('massColoringInput');cb.checked=s.mass;setMassMode(s.mass);
    document.getElementById('demoNarration').textContent=s.narration;
    document.getElementById('stepLabel').textContent=(stepIdx+1)+'/'+steps.length+' · '+s.title;
  }
  window.nextStep=function(){applyStep(stepIdx+1);};
  window.prevStep=function(){applyStep(stepIdx-1);};

  // ---- init ----
  recolor();updateLegend();applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

